:root{
  --bg:#ffffff;
  --surface:#ffffff;
  --muted:#f6f7fb;
  --ink:#0a0a23;
  --ink-2:#15153a;
  --sub:#4a4a68;
  --border:rgba(10,10,35,.12);
  --primary:#0a0a23;
  --accent:#feac32;
  --link:#002ead;
  --shadow:0 10px 30px rgba(10,10,35,.08);
  --radius:16px;
  --radius-sm:12px;
  --max:1120px;
}

*{box-sizing:border-box;}
html,body{height:100%;}
body{
  margin:0;
  font-family:Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  color:var(--ink);
  background:var(--bg);
  line-height:1.55;
}
img{max-width:100%; display:block;}
a{color:var(--link); text-decoration:none;}
a:hover{text-decoration:underline;}

.container{max-width:var(--max); margin:0 auto; padding:0 20px;}
.skip{position:absolute; left:-9999px; top:auto; width:1px; height:1px; overflow:hidden;}
.skip:focus{left:16px; top:16px; width:auto; height:auto; padding:10px 12px; background:#fff; border:1px solid var(--border); border-radius:12px; z-index:9999;}

/* Header */
.site-header{background:var(--primary); color:#fff; position:sticky; top:0; z-index:50;}
.site-header .bar{display:flex; align-items:center; gap:14px; padding:14px 0;}
.brand{display:flex; align-items:center; gap:10px; min-width:220px;}
.logo{
  width:34px; height:34px; border-radius:10px;
  background:linear-gradient(135deg, rgba(254,172,50,.95), rgba(254,172,50,.55));
  box-shadow:0 8px 20px rgba(254,172,50,.18);
}
.brand .name{font-weight:750; letter-spacing:.2px; color:#fff;}
.brand a{display:flex; align-items:center; gap:10px; text-decoration:none;}

.search{
  flex:1;
  display:flex;
  align-items:center;
  background:rgba(255,255,255,.09);
  border:1px solid rgba(255,255,255,.14);
  border-radius:999px;
  padding:8px 12px;
  min-width:200px;
}
.search input{
  width:100%;
  background:transparent;
  border:0;
  outline:0;
  color:#fff;
  font-size:14px;
}
.search input::placeholder{color:rgba(255,255,255,.72);}

.nav{display:flex; align-items:center; gap:16px;}
.nav a{color:rgba(255,255,255,.9); font-weight:600; font-size:14px;}
.nav a:hover{color:#fff; text-decoration:none;}
.nav a.cta{background:rgba(254,172,50,.12); border:1px solid rgba(254,172,50,.45); padding:8px 12px; border-radius:999px; color:#fff;}
.nav a.cta:hover{background:rgba(254,172,50,.2);}

.menu-btn{
  display:none;
  align-items:center;
  justify-content:center;
  width:40px; height:40px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.18);
  background:rgba(255,255,255,.08);
  color:#fff;
}
.menu-btn:focus-visible{outline:3px solid rgba(254,172,50,.55); outline-offset:2px;}

.mobile-nav{
  display:none;
  border-top:1px solid rgba(255,255,255,.12);
  background:rgba(10,10,35,.98);
}
.mobile-nav.open{display:block;}
.mobile-nav .container{padding:10px 20px 16px;}
.mobile-nav a{display:block; padding:10px 0; color:rgba(255,255,255,.92); font-weight:650;}
.mobile-nav a.cta{margin-top:6px; display:inline-block; padding:10px 14px; border-radius:999px; background:rgba(254,172,50,.14); border:1px solid rgba(254,172,50,.45);}

/* Banner */
.banner{
  background:linear-gradient(90deg, rgba(10,10,35,1) 0%, rgba(10,10,35,.94) 50%, rgba(10,10,35,1) 100%);
  color:#fff;
}
.banner a{color:#fff; text-decoration:none;}
.banner .inner{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:14px 0;}
.banner .headline{font-weight:750; letter-spacing:.2px;}
.banner .pill{
  display:inline-flex; align-items:center; gap:8px;
  padding:8px 12px;
  border-radius:999px;
  background:rgba(254,172,50,.14);
  border:1px solid rgba(254,172,50,.45);
  white-space:nowrap;
  font-weight:650;
}

/* Main */
main{padding:28px 0 44px;}
.section-title{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin:0 0 14px;}
.section-title h2{margin:0; font-size:22px; letter-spacing:.2px;}
.section-title p{margin:0; color:var(--sub); font-size:14px;}

/* Cards */
.grid{display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:18px;}
.card{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius);
  box-shadow:0 0 0 rgba(0,0,0,0);
  overflow:hidden;
  transition:transform .15s ease, box-shadow .15s ease, border-color .15s ease;
}
.card:hover{transform:translateY(-2px); box-shadow:var(--shadow); border-color:rgba(10,10,35,.18);}
.card .thumb{
  aspect-ratio: 16 / 9;
  background:linear-gradient(135deg, rgba(10,10,35,.16), rgba(254,172,50,.22));
  position:relative;
}
.tag{
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-weight:800;
  font-size:12px;
  letter-spacing:.2px;
  color:var(--primary);
  background:rgba(254,172,50,.2);
  border:1px solid rgba(254,172,50,.5);
  border-radius:999px;
  padding:6px 10px;
}
.thumb .tag{position:absolute; left:12px; top:12px;}

.card .body{padding:14px 14px 12px;}
.card h3{margin:8px 0 12px; font-size:18px; line-height:1.25; letter-spacing:.2px;}
.card h3 a{color:var(--ink); text-decoration:none;}
.card h3 a:hover{text-decoration:underline;}

.meta{display:flex; align-items:center; justify-content:space-between; gap:12px; color:var(--sub); font-size:13px;}
.author{display:flex; align-items:center; gap:10px; min-width:0;}
.avatar{
  width:28px; height:28px; border-radius:999px;
  background:linear-gradient(135deg, rgba(0,46,173,.35), rgba(254,172,50,.45));
  border:1px solid rgba(10,10,35,.18);
}
.author .name{font-weight:650; color:var(--ink-2); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.time{white-space:nowrap;}

/* Featured */
.featured{
  display:grid;
  grid-template-columns: 1.35fr .65fr;
  gap:18px;
  align-items:stretch;
  margin-bottom:26px;
}
.featured .hero{
  border-radius:calc(var(--radius) + 4px);
  overflow:hidden;
  border:1px solid rgba(10,10,35,.12);
  box-shadow:var(--shadow);
  background:linear-gradient(135deg, rgba(10,10,35,.12), rgba(254,172,50,.24));
}
.featured .hero .thumb{aspect-ratio: 21 / 9;}
.featured .hero .body{padding:18px 18px 16px; background:rgba(255,255,255,.92); backdrop-filter:saturate(160%) blur(10px);}
.featured .hero h1{margin:10px 0 12px; font-size:28px; line-height:1.15; letter-spacing:.2px;}
.featured .hero h1 a{color:var(--ink); text-decoration:none;}
.featured .hero h1 a:hover{text-decoration:underline;}

.featured .aside{display:flex; flex-direction:column; gap:12px;}
.aside .note{padding:16px; border:1px solid var(--border); border-radius:var(--radius); background:var(--muted);}
.aside .note h3{margin:0 0 6px; font-size:15px;}
.aside .note p{margin:0; color:var(--sub); font-size:14px;}
.aside .mini{padding:16px; border:1px solid var(--border); border-radius:var(--radius);}
.aside .mini h3{margin:0 0 8px; font-size:15px;}
.aside .mini a{font-weight:700;}

/* Buttons */
.btn{
  display:inline-flex; align-items:center; justify-content:center;
  gap:8px;
  padding:11px 14px;
  border-radius:999px;
  border:1px solid rgba(10,10,35,.18);
  background:#fff;
  color:var(--ink);
  font-weight:750;
  cursor:pointer;
}
.btn:hover{box-shadow:0 10px 20px rgba(10,10,35,.08);}
.btn.primary{background:rgba(254,172,50,.22); border-color:rgba(254,172,50,.55);}
.btn.primary:hover{background:rgba(254,172,50,.28);}

.center{display:flex; justify-content:center; margin-top:20px;}

/* Learn page */
.lead{
  border:1px solid var(--border);
  border-radius:var(--radius);
  background:linear-gradient(135deg, rgba(10,10,35,.03), rgba(254,172,50,.12));
  padding:18px;
  margin-bottom:18px;
}
.lead h1{margin:0 0 6px; font-size:26px; letter-spacing:.2px;}
.lead p{margin:0; color:var(--sub);}

.syllabus{display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:14px;}
.path{
  border:1px solid var(--border);
  border-radius:var(--radius);
  padding:14px;
  background:#fff;
}
.path .icon{
  width:38px; height:38px; border-radius:12px;
  background:rgba(0,46,173,.1);
  border:1px solid rgba(0,46,173,.18);
  display:flex; align-items:center; justify-content:center;
  font-weight:900; color:rgba(0,46,173,.9);
}
.path h3{margin:10px 0 6px; font-size:16px; line-height:1.25;}
.path p{margin:0; color:var(--sub); font-size:13px;}

.two-col{display:grid; grid-template-columns:1fr 1fr; gap:18px; margin-top:18px;}
.panel{border:1px solid var(--border); border-radius:var(--radius); background:#fff; padding:16px;}
.panel h2{margin:0 0 10px; font-size:18px;}
.panel ul{margin:0; padding-left:18px; color:var(--sub);}
.panel a{font-weight:700;}

/* Donate */
.donate-hero{
  display:grid; grid-template-columns: 1.2fr .8fr; gap:18px;
  align-items:start; margin-bottom:18px;
}
.donate-hero .copy{border:1px solid var(--border); border-radius:var(--radius); padding:18px; background:#fff;}
.donate-hero h1{margin:0 0 10px; font-size:30px; letter-spacing:.2px;}
.donate-hero p{margin:0; color:var(--sub);}

.donation-box{
  border:1px solid rgba(254,172,50,.5);
  border-radius:var(--radius);
  background:linear-gradient(135deg, rgba(254,172,50,.14), rgba(10,10,35,.03));
  padding:16px;
}
.amount-tabs{display:flex; gap:8px; flex-wrap:wrap;}
.amount-tabs button{
  flex:1;
  min-width:68px;
  padding:10px 12px;
  border-radius:999px;
  border:1px solid rgba(10,10,35,.18);
  background:#fff;
  font-weight:850;
  cursor:pointer;
}
.amount-tabs button[aria-pressed="true"]{
  background:rgba(10,10,35,1);
  color:#fff;
  border-color:rgba(10,10,35,1);
}
.amount-desc{margin:12px 0 14px; color:var(--ink-2); font-weight:650;}
.subtle{color:var(--sub); font-size:13px;}

.stats{display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:12px;}
.stat{border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; background:#fff;}
.stat .k{font-weight:900; font-size:18px;}
.stat .l{color:var(--sub); font-size:13px;}

.accordion{border:1px solid var(--border); border-radius:var(--radius); overflow:hidden; background:#fff;}
.acc-item + .acc-item{border-top:1px solid var(--border);}
.acc-btn{
  width:100%;
  text-align:left;
  padding:14px 14px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  background:#fff;
  border:0;
  cursor:pointer;
  font-weight:800;
}
.acc-btn:focus-visible{outline:3px solid rgba(254,172,50,.55); outline-offset:-3px;}
.acc-panel{max-height:0; overflow:hidden; transition:max-height .25s ease;}
.acc-panel .inner{padding:0 14px 14px; color:var(--sub);}
.acc-item.open .acc-panel{max-height:320px;}

/* Tag pages */
.tag-head{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin:8px 0 18px;}
.tag-head h1{margin:0; font-size:30px; letter-spacing:.2px;}
.tag-head .count{color:var(--sub); font-weight:650;}

.tag-row{
  display:flex;
  gap:10px;
  overflow:auto;
  padding:10px 0 16px;
  margin-bottom:10px;
}
.tag-chip{
  flex:0 0 auto;
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding:9px 12px;
  border-radius:999px;
  border:1px solid var(--border);
  background:#fff;
  font-weight:750;
  color:var(--ink);
  text-decoration:none;
}
.tag-chip .n{color:var(--sub); font-weight:700;}
.tag-chip:hover{box-shadow:0 12px 20px rgba(10,10,35,.08); text-decoration:none;}

/* Footer */
.site-footer{border-top:1px solid var(--border); background:linear-gradient(180deg, rgba(246,247,251,1), rgba(255,255,255,1));}
.site-footer .wrap{padding:30px 0 36px;}
.footer-grid{display:grid; grid-template-columns: 1.4fr 1fr; gap:18px;}
.site-footer p{margin:0 0 12px; color:var(--sub);}
.footer-links{display:flex; flex-wrap:wrap; gap:10px;}
.footer-links a{color:var(--ink-2); font-weight:650;}
.trending{display:flex; flex-wrap:wrap; gap:8px;}
.trending a{font-size:13px; padding:8px 10px; border-radius:999px; background:#fff; border:1px solid var(--border); color:var(--ink-2); font-weight:650;}

/* Responsive */
@media (max-width: 980px){
  .grid{grid-template-columns:repeat(2, minmax(0,1fr));}
  .featured{grid-template-columns:1fr;}
  .featured .hero .thumb{aspect-ratio: 16 / 9;}
  .syllabus{grid-template-columns:repeat(2, minmax(0,1fr));}
  .donate-hero{grid-template-columns:1fr;}
  .stats{grid-template-columns:repeat(2, minmax(0,1fr));}
}
@media (max-width: 740px){
  .nav{display:none;}
  .menu-btn{display:inline-flex;}
  .grid{grid-template-columns:1fr;}
  .syllabus{grid-template-columns:1fr;}
  .two-col{grid-template-columns:1fr;}
  .footer-grid{grid-template-columns:1fr;}
  .brand{min-width:auto;}
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce){
  *{scroll-behavior:auto !important;}
  .card, .acc-panel{transition:none !important;}
}
